static async hasPendingInviteByUserId({ userId }: { userId: number }): Promise<boolean> {
    const pendingInvite = await prisma.membership.findFirst({
      where: {
        userId,
        accepted: true,
      },
      select: {
        id: true,
      },
    });
    return !!pendingInvite;
  }

// Determine which onboarding path to use
  const onboardingV3Enabled = await featuresRepository.checkIfFeatureIsEnabledGlobally("onboarding-v3");

  const hasPendingInvite = await MembershipRepository.hasPendingInviteByUserId({ userId });

  if (hasPendingInvite || onboardingV3Enabled) {
    return "/onboarding/personal/settings";
  }

  return onboardingV3Enabled ? "/onboarding/getting-started" : "/getting-started";

findings.body:
The new method is meant to find pending invites, but it filters on `accepted: true`:

::diff{file="packages/features/membership/repositories/MembershipRepository.ts" lines="584-595"}

It returns `true` for anyone who has already joined a team and `false` for a user whose only membership is an unaccepted invite. That's the opposite of the intent. The original inline query in `onboardingUtils.ts` used `accepted: false`.

The effects:
- Invited users signing up with a token still see the plan-selection page, which is exactly what this PR is supposed to fix.
- Existing team members who open `/onboarding/getting-started` (for example to create a team or org) get redirected to personal settings and can't reach plan selection.
- Tests 1 and 2 in the new integration test file will fail against this implementation.

